CREATE TABLE IF NOT EXISTS `verification_code` (`id` BIGINT NOT NULL AUTO_INCREMENT, `target` VARCHAR(50) NOT NULL, `target_type` TINYINT NOT NULL, `scene` TINYINT NOT NULL, `code` VARCHAR(10) NOT NULL, `expires_at` DATETIME NOT NULL, `used` TINYINT DEFAULT 0, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_target_scene` (`target`, `target_type`, `scene`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
